window.dayjs = function dayjs(input) {
  const date = input ? new Date(input) : new Date();
  return {
    $d: date,
    format(pattern) {
      const pad = (value) => String(value).padStart(2, "0");
      return pattern
        .replace("YYYY", date.getFullYear())
        .replace("MM", pad(date.getMonth() + 1))
        .replace("DD", pad(date.getDate()));
    },
    subtract(amount, unit) {
      const next = new Date(date);
      if (unit.startsWith("day")) next.setDate(next.getDate() - amount);
      if (unit.startsWith("month")) next.setMonth(next.getMonth() - amount);
      if (unit.startsWith("year")) next.setFullYear(next.getFullYear() - amount);
      return window.dayjs(next);
    },
    startOf(unit) {
      const next = new Date(date);
      if (unit === "day") next.setHours(0, 0, 0, 0);
      if (unit === "month") next.setDate(1), next.setHours(0, 0, 0, 0);
      if (unit === "year") next.setMonth(0, 1), next.setHours(0, 0, 0, 0);
      return window.dayjs(next);
    },
    endOf(unit) {
      const next = new Date(date);
      if (unit === "day") next.setHours(23, 59, 59, 999);
      if (unit === "month") next.setMonth(next.getMonth() + 1, 0), next.setHours(23, 59, 59, 999);
      if (unit === "year") next.setMonth(11, 31), next.setHours(23, 59, 59, 999);
      return window.dayjs(next);
    },
    valueOf() {
      return date.valueOf();
    },
    isValid() {
      return !Number.isNaN(date.valueOf());
    }
  };
};
